insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'auditory-processing-speed'), 'overall', 0, 30, 'Developing', 'Holding a spoken sequence in mind — especially in reverse — is difficult right now, and minimally-different word pairs are easy to mishear.', ARRAY['Practice with shorter sequences first (3-4 digits) before attempting longer ones', 'For backward spans, try picturing the digits appearing one at a time, then read them off in reverse from that mental image', 'Listen for the specific sound that differs in word pairs (first sound, middle vowel, last sound) rather than judging the whole word at once']::text[], NULL, 1);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'auditory-processing-speed'), 'overall', 31, 50, 'Average', 'Shorter spans are manageable, but longer sequences and backward recall specifically show real strain.', ARRAY['Backward span is meant to be substantially harder than forward — a big gap between the two is normal, not a red flag', 'Practice minimal-pair listening specifically (many free speech-perception exercises use exactly this format)']::text[], NULL, 2);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'auditory-processing-speed'), 'overall', 51, 70, 'Strong', 'Reliable recall across most sequence lengths, both forward and backward, with solid auditory discrimination.', ARRAY['Push toward longer sequences (7+ digits) to find your actual ceiling', convert_from(decode('Tm90aWNlIHdoZXRoZXIgZm9yd2FyZCBvciBiYWNrd2FyZCBzcGFuIGlzIHlvdXIgcmVsYXRpdmUgc3RyZW5ndGgg4oCUIHRoYXQncyBpbmZvcm1hdGl2ZSBhYm91dCB5b3VyIGF1ZGl0b3J5IHdvcmtpbmctbWVtb3J5IHN0eWxl', 'base64'), 'UTF8')]::text[], NULL, 3);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'auditory-processing-speed'), 'overall', 71, 85, 'Very Strong', 'Strong auditory working memory in both directions, plus fast, accurate discrimination of similar-sounding words.', ARRAY['This is a genuine asset for verbal-heavy, listening-intensive work — meetings, interpretation, live instruction-following', convert_from(decode('Q29tcGFyZSB0aGlzIHdpdGggeW91ciB2aXN1YWwvc3BhdGlhbCBtZW1vcnkgcmVzdWx0cyDigJQgYXVkaXRvcnkgYW5kIHZpc3VhbCB3b3JraW5nIG1lbW9yeSBkb24ndCBhbHdheXMgdHJhY2sgdG9nZXRoZXI=', 'base64'), 'UTF8')]::text[], NULL, 4);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'auditory-processing-speed'), 'overall', 86, 100, 'Exceptional', 'Near-ceiling performance across digit span forward, backward, and auditory discrimination.', ARRAY['This is an elite auditory-processing result across every task type tested', 'Consider fields that specifically reward fast, accurate listening under real time pressure']::text[], NULL, 5);
